  var BY = {}; M.forEach(function (m) { BY[m.id] = m; });

  // ---------- storage ----------
  function scope() { return BM.ui.mtScope || '_'; }
  function store(m) {
    var all = BM.state.methods = BM.state.methods || {};
    var sc = all[scope()] = all[scope()] || {};
    if (!sc[m.id]) sc[m.id] = fresh(m);
    return sc[m.id];
  }
  function fresh(m) {
    var d = {};
    if (m.blocks) { d.blocks = {}; m.blocks.forEach(function (b) { d.blocks[b[0]] = ['']; }); }
    if (m.kind === 'table') { d.rows = JSON.parse(JSON.stringify(m.seed || [])); if (m.axes) d.axes = JSON.parse(JSON.stringify(m.axes)); }
    if (m.kind === 'matrix') { d.players = m.players.slice(); d.rows = m.rows.map(function (r) { return { name: r[0], w: r[1] || 3, s: m.players.map(function (p, j) { return r[2] ? r[2][j] : 3; }) }; }); }
    if (m.kind === 'funnel') d.v = { shows: 120000, clicks: 4200, cart: 290, orders: 110, buys: 96, price: 590, spend: 15000 };
    if (m.kind === 'market') d.v = { people: 2000000, need: 30, freq: 4, price: 500, sam: 35, som: 2 };
    if (m.kind === 'vw') d.text = '250 400 600 800\n300 450 650 900\n200 350 500 700\n350 500 700 950\n300 400 550 750\n400 550 750 1000\n250 350 500 650\n450 600 800 1100\n300 500 650 850\n350 450 600 800\n500 650 850 1200\n200 300 450 600';
    return d;
  }
  var save = BM.debounce(function () { BM.persist(); }, 600);
  function nv(v) { var x = BM.num(v); return x == null ? 0 : x; }
  function rub(v) { return v == null || !isFinite(v) ? '—' : Math.round(v).toLocaleString('ru-RU') + ' ₽'; }
  function pc(v, d) { return v == null || !isFinite(v) ? '—' : v.toLocaleString('ru-RU', { maximumFractionDigits: d == null ? 1 : d }) + '%'; }
  function bars(rows, fmt) {
    var max = Math.max.apply(null, rows.map(function (r) { return Math.abs(r.v); }).concat([0.0001]));
    return '<ul class="cf-bars" role="list">' + rows.map(function (r) {
      return '<li><span class="cf-bar-l">' + esc(r.l) + '</span><span class="cf-bar-t"><i class="' + (r.cls || '') + '" style="width:' + (Math.abs(r.v) / max * 100).toFixed(1) + '%"></i></span><span class="cf-bar-v num">' + (fmt ? fmt(r.v) : r.v) + (r.tag ? '<small>' + esc(r.tag) + '</small>' : '') + '</span></li>';
    }).join('') + '</ul>';
  }

