    if (s.type === 'matrix') {
      return '<div class="mt-matrix"><div class="mt-m-y"><span>' + esc(s.y[0]) + '</span><span>' + esc(s.y[1]) + '</span></div><div><div class="mt-m-x"><span>' + esc(s.x[0]) + '</span><span>' + esc(s.x[1]) + '</span></div>' +
        '<div class="mt-m-grid">' + s.cells.map(function (c, i) { return '<div class="mt-m-cell q' + i + '">' + esc(c) + '</div>'; }).join('') + '</div></div></div>';
    }
    if (s.type === 'funnel') return '<div class="mt-funnel">' + s.stages.map(function (x, i) { return '<div style="width:' + (100 - i * (60 / s.stages.length)) + '%">' + esc(x) + '</div>'; }).join('') + '</div>';
    if (s.type === 'nested') return '<div class="mt-nested"><div><span>' + esc(s.labels[0]) + '</span><div><span>' + esc(s.labels[1]) + '</span><div><span>' + esc(s.labels[2]) + '</span></div></div></div></div>';
